export interface SeedFeature {
  icon: string;
  title: string;
  description: string;
}
export interface SeedFaq {
  q: string;
  a: string;
}
export interface SeedBundle {
  key: string;
  label: string;
  shortLabel: string;
  description: string;
  quantity: number;
  /** Regular price (₦). */
  price: number;
  /** Promo price (₦), charged only until the seed promo deadline (PROMO_ENDS_AT in index.ts). */
  promo?: number;
  compareAt: number | null;
  tag?: string;
  sideTag?: string;
  note?: string;
  popular?: boolean;
}
export interface SeedGift {
  name: string;
  value: number;
  image?: string;
  conditions: string;
  /** Gift is part of the promo and stops at the promo deadline. */
  endsWithPromo?: boolean;
}
export interface SeedProduct {
  slug: string;
  name: string;
  category: string;
  price: number;
  compareAt: number | null;
  short: string;
  description: string;
  images: { file: string; alt: string }[];
  tags: string[];
  imageBadge?: { text: string; style: "navy" | "emerald" | "gold" | "bronze" | "red"; icon: string };
  perk?: { text: string; icon: string; style: "gold" | "neutral" };
  deliveryNote?: { text: string; icon: string };
  curated?: { rank: number; label: string };
  podAvailable?: boolean;
  warrantyMonths?: number;
  specs?: { label: string; value: string }[];
  features?: SeedFeature[];
  faqs?: SeedFaq[];
  bundles?: SeedBundle[];
  gift?: SeedGift;
  /** Flash deal (₦ price) ending at the promo deadline. */
  flash?: { price: number; title: string; promoText: string | null; sort: number };
  /** units per hub: [lagos, abuja, warehouse]; batch = units received in the current batch (admin data, not shown) */
  stock: [number, number, number];
  batch?: [number, number, number];
  ageDays: number; // for "Newest" sort
}

const img = (file: string, alt: string) => ({ file, alt });
const ph = (slug: string, alt: string) => img(`ph-${slug}.webp`, alt);

