const DEFAULT_FAQS: SeedFaq[] = [
  { q: "How do I pay?", a: "Place your order on this page, then tap “Complete Payment on WhatsApp”. Our team confirms your order in chat and shares MUBAZZAR's official payment details. Pay on Delivery can be arranged in chat. We never ask for card PINs or OTPs." },
  { q: "How long will delivery take?", a: "Lagos and Abuja orders placed before the daily cut-off can arrive the same day. Other states take 2–4 working days. Your exact fee and delivery time show when you choose your state." },
  { q: "What if it arrives faulty?", a: "Every item is tested before dispatch. If anything is defective, message us within 7 days for a free swap or refund." },
];

export function faqsFor(p: SeedProduct): SeedFaq[] {
  return p.faqs ?? DEFAULT_FAQS;
}

export function featuresFor(p: SeedProduct): SeedFeature[] {
  return (
    p.features ?? [
      { icon: "fact_check", title: "Tested before dispatch", description: "Unboxed and checked by our team in Lagos before it ships to you." },
      { icon: "local_shipping", title: "Fast nationwide delivery", description: "Same-day in Lagos & Abuja before cut-off; 2–4 working days elsewhere." },
      { icon: "currency_exchange", title: "7-day swap guarantee", description: "Faulty on arrival? We replace it free." },
    ]
  );
}
